import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

// Fallback embedded assets (ensures watermark works 100% on Production / Vercel / VPS / Serverless)
const EMBEDDED_LOGO_B64 = "";
const EMBEDDED_FONT_B64 = "";

export function getWatermarkLogoBuffer(): Buffer {
  const possiblePaths = [
    path.join(process.cwd(), "public/images/java_batik_gold.png"),
    path.join(process.cwd(), "dist/client/images/java_batik_gold.png"),
    path.join(process.cwd(), "client/images/java_batik_gold.png"),
    path.join(process.cwd(), "images/java_batik_gold.png"),
  ];

  try {
    const currentDir = path.dirname(fileURLToPath(import.meta.url));
    possiblePaths.push(
      path.join(currentDir, "../../public/images/java_batik_gold.png"),
      path.join(currentDir, "../client/images/java_batik_gold.png"),
      path.join(currentDir, "../../../public/images/java_batik_gold.png")
    );
  } catch (e) {}

  for (const p of possiblePaths) {
    try {
      if (fs.existsSync(p)) {
        return fs.readFileSync(p);
      }
    } catch (e) {}
  }

  // Fallback to embedded Base64 buffer
  return Buffer.from(EMBEDDED_LOGO_B64, "base64");
}

export function getWatermarkFontBase64(): string {
  const possiblePaths = [
    path.join(process.cwd(), "public/fonts/Roboto-Bold.ttf"),
    path.join(process.cwd(), "dist/client/fonts/Roboto-Bold.ttf"),
    path.join(process.cwd(), "client/fonts/Roboto-Bold.ttf"),
    path.join(process.cwd(), "fonts/Roboto-Bold.ttf"),
  ];

  try {
    const currentDir = path.dirname(fileURLToPath(import.meta.url));
    possiblePaths.push(
      path.join(currentDir, "../../public/fonts/Roboto-Bold.ttf"),
      path.join(currentDir, "../client/fonts/Roboto-Bold.ttf"),
      path.join(currentDir, "../../../public/fonts/Roboto-Bold.ttf")
    );
  } catch (e) {}

  for (const p of possiblePaths) {
    try {
      if (fs.existsSync(p)) {
        return fs.readFileSync(p).toString("base64");
      }
    } catch (e) {}
  }

  // Fallback to embedded Base64 font
  return EMBEDDED_FONT_B64;
}
